// amber.score - the example the tests and CI compile.
//
// Deliberately audible: pads holding the harmony, a bass on the roots, a lead
// line over the top and a second voice answering it. A compile that produces
// silence is obviously wrong.

song {
  title "Amber"
  tempo 96 bpm
  meter 4/4
  grid  auto
  key   F minor
  seed  0x5EEDC0FFEE
}

channel pad {
  mixer    1
  range    C3..C5
  velocity 52 +- 6
}

channel bass {
  mixer    2
  range    E1..E3
  velocity 76 +- 4
}

channel lead {
  mixer    3
  range    F4..A5
  velocity 66 +- 8
}

channel answer {
  mixer    4
  range    F3..F5
  velocity 54 +- 6 per bar
}

voicing warm {
  size     4 voices
  spread   drop2
  register C3..C5
  motion   smooth
  maxLeap  7
  bass     from-inversion
}

rhythm held    { 1/1 }
rhythm pulse   { 1/4 1/4 1/2 }
rhythm running { 1/8 x6 - 1/8 1/8 }

harmony lament {
  i x2 | bVI | bVII | i^1 x2 | iv | V7/iv
}

harmony lift {
  bVI | bVII | i x2 | bVI | bVII | V7 | i
}

section intro {
  length 4 bars
  harmony {
    i 2 bars | bVI 1 bar | V7 1 bar
  }
  part pad {
    chords with warm
    rhythm held
  }
}

section verse {
  length 8 bars
  harmony lament
  part pad {
    chords with warm
    rhythm held
  }
  part bass {
    line root-fifth
    rhythm pulse
  }
  part lead {
    melody {
      rhythm       pulse
      articulation legato
      contour      arch
      strong       chord-tones
      variance     0.25
      mute         1 of 4
      cadence      choose [1 3 5] per instance
    }
  }
  part answer {
    counterpoint against lead {
      rhythm               pulse
      parallel-fifths      forbid
      parallel-octaves     forbid
      voice-crossing       forbid
      dissonance-on-strong soft 3
      leaps                soft 1.5
      repeats              soft 1
    }
  }
}

section chorus {
  length 8 bars
  harmony lift
  part pad {
    chords with warm
    rhythm pulse
  }
  part bass {
    line root
    rhythm running
  }
  part lead {
    melody {
      rhythm   running
      contour  rise
      strong   chord-tones
      variance 0.4
    }
  }
}

arrangement {
  intro
  verse
  verse as verse_b
  chorus
  verse
  chorus x2 identical
}

// drift.score - the music behind the Wavetable demo.
//
// The notes are here; the SOUND is not. Every channel below is adopted by name
// in Demos.cpp and dressed there: five different wavetables, unison stacks, and
// a morph position that moves under an LFO on the held voices and under the
// envelope on the struck ones. That split is the language's own - it owns
// notes, patterns and clips, and the user owns the instrument and the mixer.
//
// Slow on purpose. A wavetable morph is a thing you hear over bars, not beats,
// so the parts hold and the harmony turns underneath them.

song {
  title "Drift"
  tempo 84 bpm
  meter 4/4
  grid  auto
  key   D minor
  seed  0x0DEFACEDBEEF
}

channel pad {
  mixer    1
  range    C3..C5
  velocity 48 +- 5
}

channel swell {
  mixer    2
  range    G3..G5
  velocity 40 +- 6
}

channel sub {
  mixer    3
  range    D1..D3
  velocity 78 +- 3
}

channel bell {
  mixer    4
  range    D4..D6
  velocity 58 +- 9
}

channel answer {
  mixer    5
  range    A3..A5
  velocity 44 +- 6 per bar
}

voicing wide {
  size     4 voices
  spread   open
  register C3..C5
  motion   smooth
  maxLeap  5
  bass     from-inversion
}

voicing upper {
  size     3 voices
  spread   shell
  register G3..G5
  motion   smooth
}

rhythm hold    { 1/1 }
rhythm breathe { 1/2 1/2 }
rhythm drift   { 1/4 1/4 1/2 }
rhythm shimmer { 1/8 x6 - 1/8 1/8 }

harmony still {
  i x2 | bVI x2 | iv x2 | bVII x2
}

harmony opening {
  bVI | bVII | i x2 | iv | V7 | i x2
}

section haze {
  length 4 bars
  harmony {
    i 2 bars | bVI 1 bar | bVII 1 bar
  }
  part pad {
    chords with wide
    rhythm hold
  }
}

section gather {
  length 8 bars
  harmony still
  part pad {
    chords with wide
    rhythm hold
  }
  part swell {
    chords with upper
    rhythm breathe
  }
  part sub {
    line root
    rhythm breathe
  }
}

section bloom {
  length 8 bars
  harmony opening
  part pad {
    chords with wide
    rhythm breathe
  }
  part swell {
    chords with upper
    rhythm drift
  }
  part sub {
    line root-fifth
    rhythm drift
  }
  part bell {
    melody {
      rhythm       shimmer
      articulation legato
      contour      arch
      strong       chord-tones
      variance     0.35
      mute         1 of 4
      cadence      choose [1 3 5] per instance
    }
  }
  part answer {
    counterpoint against bell {
      rhythm               drift
      parallel-fifths      forbid
      parallel-octaves     forbid
      voice-crossing       forbid
      dissonance-on-strong soft 3
      leaps                soft 1.5
      repeats              soft 1
    }
  }
}

section ebb {
  length 8 bars
  harmony still
  part pad {
    chords with wide
    rhythm hold
  }
  part sub {
    line root
    rhythm breathe
  }
  part bell {
    melody {
      rhythm   drift
      contour  fall
      strong   chord-tones
      variance 0.2
      mute     1 of 3
    }
  }
}

section fade {
  length 4 bars
  harmony {
    iv 1 bar | bVII 1 bar | i 2 bars
  }
  part pad {
    chords with wide
    rhythm hold
  }
}

arrangement {
  haze
  gather
  bloom
  ebb
  fade
}

// neon.score - the music behind the Oscillator Stack demo.
//
// Four parts and nothing exotic in the writing, on purpose: this demo is about
// what ONE channel is made of, and a busy arrangement would talk over it. Each
// channel below is adopted by name in Demos.cpp and given three oscillators -
// an octave apart, a few cents off each other, at different gains - which is
// the whole of the sound and none of the notes.

song {
  title "Neon"
  tempo 108 bpm
  meter 4/4
  grid  auto
  key   C minor
  seed  0x00FF1CE5EED
}

channel lead {
  mixer    1
  range    C4..C6
  velocity 70 +- 7
}

channel pad {
  mixer    2
  range    C3..C5
  velocity 46 +- 5
}

channel bass {
  mixer    3
  range    C1..C3
  velocity 82 +- 4
}

channel arp {
  mixer    4
  range    G3..G5
  velocity 58 +- 8 per bar
}

voicing bed {
  size     4 voices
  spread   open
  register C3..C5
  motion   smooth
  maxLeap  7
  bass     from-inversion
}

rhythm held    { 1/1 }
rhythm halves  { 1/2 1/2 }
rhythm pulse   { 1/4 1/4 1/2 }
rhythm running { 1/8 x6 - 1/8 1/8 }

harmony engine {
  i x2 | bVI x2 | bIII x2 | bVII x2
}

harmony lift {
  bVI | bVII | i x2 | bIII | bVII | i x2
}

section neon_intro {
  length 4 bars
  harmony {
    i 2 bars | bVI 1 bar | bVII 1 bar
  }
  part pad {
    chords with bed
    rhythm held
  }
  part bass {
    line root
    rhythm halves
  }
}

section verse {
  length 8 bars
  harmony engine
  part pad {
    chords with bed
    rhythm held
  }
  part bass {
    line root-fifth
    rhythm pulse
  }
  part arp {
    melody {
      rhythm       running
      articulation detached
      contour      wave
      strong       chord-tones
      variance     0.3
      align        continuous
    }
  }
}

section chorus {
  length 8 bars
  harmony lift
  part pad {
    chords with bed
    rhythm halves
  }
  part bass {
    line root
    rhythm running
  }
  part arp {
    melody {
      rhythm   running
      contour  rise
      strong   chord-tones
      variance 0.4
      align    continuous
    }
  }
  part lead {
    melody {
      rhythm       pulse
      articulation legato
      contour      arch
      strong       chord-tones
      variance     0.25
      leap         max 7 resolve step
      cadence      choose [1 3 5] per instance
    }
  }
}

section outro {
  length 4 bars
  harmony {
    bVI 1 bar | bVII 1 bar | i 2 bars
  }
  part pad {
    chords with bed
    rhythm held
  }
  part bass {
    line root
    rhythm halves
  }
}

arrangement {
  neon_intro
  verse
  chorus
  verse as verse_b
  outro
}
